ags', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'tags') THEN CASE WHEN p_manifest_path IS NOT NULL AND position('"tags"' in p_manifest_path) > 0 THEN nexus.catalog_tag_set(CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'tags'), 'null') <> 'null' THEN d.metadata -> 'tags' ELSE c.metadata -> 'tags' END) ELSE '[""]'::jsonb END END, 'category', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'category') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'category'), 'null') <> 'null' THEN d.metadata -> 'category' ELSE COALESCE(NULLIF(c.metadata -> 'category', 'null'::jsonb), '""'::jsonb) END END, 'ttl_days', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'ttl_days') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'ttl_days'), 'null') <> 'null' THEN d.metadata -> 'ttl_days' ELSE COALESCE(NULLIF(c.metadata -> 'ttl_days', 'null'::jsonb), '""'::jsonb) END END, 'source_agent', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'source_agent') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'source_agent'), 'null') <> 'null' THEN d.metadata -> 'source_agent' ELSE COALESCE(NULLIF(c.metadata -> 'source_agent', 'null'::jsonb), '""'::jsonb) END END, 'extraction_method', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_method') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_method'), 'null') <> 'null' THEN d.metadata -> 'extraction_method' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_method', 'null'::jsonb), '""'::jsonb) END END, 'quality_gate_overridden', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'quality_gate_overridden') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'quality_gate_overridden'), 'null') <> 'null' THEN d.metadata -> 'quality_gate_overridden' ELSE COALESCE(NULLIF(c.metadata -> 'quality_gate_overridden', 'null'::jsonb), '""'::jsonb) END END, 'extraction_source', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'extraction_source') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'extraction_source'), 'null') <> 'null' THEN d.metadata -> 'extraction_source' ELSE COALESCE(NULLIF(c.metadata -> 'extraction_source', 'null'::jsonb), '""'::jsonb) END END, 'frecency_score', CASE WHEN nexus.manifest_names_key(p_manifest_where, p_manifest_path, 'frecency_score') THEN CASE WHEN COALESCE(jsonb_typeof(d.metadata -> 'frecency_score'), 'null') <> 'null' THEN d.metadata -> 'frecency_score' ELSE COALESCE(NULLIF(c.metadata -> 'frecency_score', 'null'::jsonb), '""'::jsonb) END END ) AS eff ) e WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND d.deleted_at IS NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) AND c.embedding_384 IS NOT NULL ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
